import logging
import os
import re
import time
import zipfile
from datetime import datetime
import xml.etree.ElementTree as ET

from ..config.loggers import LoggerAdapter4EmptyExtra
from ..exceptions import ZipFileNotFoundException


class Utils:
    def __init__(self):
        """Class providing some utility functions throughout the library"""
        raw_logger = logging.getLogger("ute_ue.uepc")
        self.logger = LoggerAdapter4EmptyExtra(raw_logger, {'area': 'UTILS'})

    def save_zipped_files(self, zip_name, save_location, files):
        """
        Create a ZIP archive containing the specified files and save it to the specified location.

        :param str zip_name: The name of the ZIP archive
        :param str save_location: The directory where the ZIP archive should be saved.
        :param List files: A list of file
        :return: None
        :raises: ZipFileNotFoundException: If file was not saved properly.
        """
        if not zip_name.lower().endswith(".zip"):
            zip_name = zip_name + ".zip"

        file_path = os.path.join(save_location, zip_name)
        if os.path.isfile(file_path):
            os.remove(file_path)
            self.logger.debug(f"Zip file with given name already existed in given location: {file_path}"
                              " and it was removed.")
        with open(file_path, 'wb') as zip_file:
            zip_file.write(files.content)
        if os.path.isfile(file_path):
            self.logger.debug(f"Zip file was saved in given path: {file_path}")
            return
        raise ZipFileNotFoundException(f"Zip file: {zip_name} was not correctly saved to given path: "
                                       f"{save_location}")

    def unpack_zip_file(self, zip_file_path):
        """
        Unpack a ZIP file.

        :param str zip_file_path: The path to the ZIP file that needs to be unpacked.
        :return: None
        """
        self.logger.info(f"Trying to unpack: {zip_file_path}")
        try:
            dir_name = os.path.dirname(zip_file_path)
            zip_file_name = os.path.basename(zip_file_path).strip('.zip')
            zip_dir = os.path.join(dir_name, zip_file_name)

            with zipfile.ZipFile(zip_file_path, 'r') as zip_ref:
                zip_ref.extractall(zip_dir)

            self.logger.info(f"Unpacked {zip_file_path} to {zip_dir}")
        except Exception as e:
            self.logger.warning(f"Unable to unpack {zip_file_path}. An error occurred: {e}")

    def list_files_from(self, path):
        """
        List all the files located under the specified directory path.

        :param str path: The directory path for which files should be listed.
        :return List: A list of filenames (without full paths) located in the specified directory.
                      If the directory is empty or doesn't exist, an empty list is returned.
        """
        self.logger.info(f"Trying to list files from: {path}")
        try:
            items = os.listdir(path)

            files = [item for item in items if os.path.isfile(os.path.join(path, item))]
            return files
        except Exception as e:
            self.logger.warning(f"Unable to list files from {path}. An error occurred: {e}")
            return []

    def remove_zip(self, file_path):
        """
        Remove a ZIP file.

        :param str file_path: The path to the ZIP file that needs to be removed after unpacking.
        """
        self.logger.info(f"removing file: {file_path}")
        try:
            os.remove(file_path)
        except Exception as e:
            self.logger.warning(f"Unable to remove filepath: {file_path}; {e}")

    def remove_directory(self, directory):  # noqa: C901
        """
        Remove a directory and its contents.

        :param str directory: The path to the directory to be removed.
        :return: None
        """
        self.logger.info(f"Trying to remove: {directory}")
        if os.path.exists(directory) and os.path.isdir(directory):
            try:
                for root, dirs, files in os.walk(directory, topdown=False):
                    # remove all files inside directory
                    for file in files:
                        file_path = os.path.join(root, file)
                        self.logger.info(f"removing file: {file_path}")
                        os.remove(file_path)
                        # remove all dirs are inside
                        for dir_to_remove in dirs:
                            dir_path = os.path.join(root, dir_to_remove)
                            if os.path.exists(dir_path) and os.path.isdir(dir_path):
                                self.logger.info(f"removing dir: {dir_path}")
                                os.rmdir(dir_path)
                self.logger.info(f"removing dir: {directory}")
                os.rmdir(directory)
            except OSError as e:
                self.logger.warning(f"Directory cleanup failed with error: {e}")
        else:
            self.logger.info(f"Directory {directory} does not exist!")


def get_all_loger_file_names():
    """
    Get the names of the files to which all the loggers write.

    :return: A list of the names of the files to which all the loggers write.
    """
    logger_file_names = []
    for logger_name in logging.root.manager.loggerDict:
        logger = logging.getLogger(logger_name)
        for handler in logger.handlers:
            if isinstance(handler, logging.FileHandler):
                logger_file_names.append(handler.baseFilename)
    return logger_file_names

def _create_zip_from_paths(zip_name, paths):  #noqa: C901
    """
    Create a ZIP archive containing the specified files and directories.

    :param str zip_name: The name of the ZIP archive to create.
    :param list paths: A list of file or directory paths to include in the ZIP archive.
    :return: None
    """
    base_log_path = ""
    allowed_file_patterns = [r"al\.[a-zA-Z0-9\_\.\-]+\.log",
                             r"moler\.[a-zA-Z0-9\_\.\-]+log",
                             r"ute_ue\.[a-zA-Z0-9\_\.\-]+log",
                             r"ue\.[a-zA-Z0-9\_\.\-]+log",
                             r"ue\_proxy\_logs[a-zA-Z0-9\_\.\-]+\.zip"]
    with zipfile.ZipFile(zip_name, 'w') as zipf:
        for path in paths:
            if os.path.isfile(path):  # Add files
                base_log_path = os.path.dirname(path) if not base_log_path else base_log_path
                if any(re.match(pattern, os.path.basename(path)) for pattern in allowed_file_patterns):
                    zipf.write(path, os.path.basename(path))
            elif os.path.isdir(path):  # Add ueproxy dirs
                for root, dirs, files in os.walk(path):
                    for file in files:
                        file_path = os.path.join(root, file)
                        rel_name = os.path.relpath(file_path, start=os.path.dirname(path))
                        zipf.write(file_path, rel_name)
        _add_rf_logs_to_zip(zipf, base_log_path)


def _add_rf_logs_to_zip(zipf, base_log_path):
    """
    Add Robot Framework log files to the ZIP archive.

    :param zipfile.ZipFile zipf: The ZIP archive to which the log files should be added.
    :param str base_log_path: The base directory where the log files are located.
    """
    rf_log_files = ["log.html", "output.xml", "report.html", "debug.log"]
    for file in rf_log_files:
        file_path = os.path.join(base_log_path, file)
        if os.path.isfile(file_path):
            zipf.write(file_path, file)


def _get_robot_filename_from_output_xml():
    """Parses the output.xml file to extract the robot filename.

    :returns: The robot filename, or None if not found.
    """
    file = "./output.xml"
    try:
        tree = ET.parse(file)
        root = tree.getroot()

        # Find the first suite element
        suite = root.find('./suite')

        # Extract the source attribute from the suite element
        if suite is not None:
            file_path = suite.get('source')
            sep = "/" if "/" in file_path else "\\"
            return str(suite.get('source')).split(sep)[-1]
    except Exception as e:  # noqa: F841
        ...  # Nothing to log here, because it is after the test
    return None


def check_log_and_post_process(log_paths, test_data, timeout=10):
    """
    Function to check if log.html is created and then trigger post-processes.

    :param list log_paths: A list of file or directory paths to include in the ZIP archive.
    :param object test_data: The test data object.
    :param int timeout: The maximum time to wait for the log.html file to be created.
    """
    start_time = time.time()
    while time.time() - start_time < timeout:
        if os.path.exists('log.html'):
            file = datetime.now().strftime("taf.ue_%Y_%m_%d__%H_%M.zip")
            files = os.listdir()
            zip_files = [zip_file for zip_file in files if re.search(pattern=r"taf.ue_[0-9_]+.zip", string=zip_file) is not None]
            if zip_files:
                for zip_file in zip_files:
                    os.remove(zip_file)
            _create_zip_from_paths(file, log_paths)
            break
        time.sleep(1)  # Check every second
    # Log test suite into ute_ue.kw_data.log
    act_robot_file = test_data.act_test_suite.robot_file
    test_data.act_test_suite.robot_file = act_robot_file or _get_robot_filename_from_output_xml()
    test_data.report_test_suite()
